// 按账号池聚合的账号调度健康投影(FE-GAP-002 第四切),服务端一次算完,不倒行给浏览器求和。
// 分母 = 该池下经未软删渠道挂接的未软删账号(含运维停用账号)。每个账号恰属一个渠道、一个池,
// 不会重复计数。分类互斥,优先级 unavailable > cooling_down > degraded > schedulable,
// 谓词逐字对齐选号候选查询(ListEligibleAccountsByPoolGroup)与进程内健康门中**与请求无关**的账号级判定;
// 按模型/协议/能力清单、模型限流、上游额度、并发与会话容量等按请求维度的门不在本投影内,
// 因此 schedulable 表示"健康层放行",不表示某个具体请求一定会选中它:
//
//	unavailable  运维停用 / 渠道停用 / 上游 provider 停用或软删 / 账号已过期 /
//	             revoked 未到期或无截止 / 无可服务凭据 / 最新 FSM disabled|manual_paused
//	cooling_down throttled|cooldown 未到期或无截止 / 最新 FSM cooling_down 且未开 disable_cooling /
//	             FSM ramping 但放量阶段为空(尚未放行任何流量)且未开 disable_cooling
//	degraded     最新 FSM degraded / FSM ramping 按比例放量(阶段非空)且未开 disable_cooling
//	schedulable  其余(数据库层与 FSM 门都放行)
//
// 最新 FSM 记录按 credential_version DESC, updated_at DESC 取,与健康门读取顺序一致;无记录视为放行。
// schedulable_ids / degraded_ids / cooling_ids(及对齐的 cooling_recovery_at)/ cooling_exempt_ids 只回传
// 各栏账号 id、冷却账号的已知恢复时刻与 disable_cooling 豁免标记,供进程内 auth 降级车道叠加
// (软冷却可被豁免,硬禁不可;硬禁的冷却账号要抬升为 unavailable 并从恢复时刻里剔除),这些 id 不进响应体。
func (q *Queries) SummarizeProviderAccountHealthByPool(ctx context.Context, tenantID int64) ([]SummarizeProviderAccountHealthByPoolRow, error) {
	rows, err := q.db.Query(ctx, summarizeProviderAccountHealthByPool, tenantID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []SummarizeProviderAccountHealthByPoolRow
	for rows.Next() {
		var i SummarizeProviderAccountHealthByPoolRow
		if err := rows.Scan(
			&i.PoolGroupID,
			&i.PoolName,
			&i.PoolEnabled,
			&i.TotalAccounts,
			&i.SchedulableAccounts,
			&i.DegradedAccounts,
			&i.CoolingDownAccounts,
			&i.UnavailableAccounts,
			&i.SchedulableIds,
			&i.DegradedIds,
			&i.CoolingIds,
			&i.CoolingRecoveryAt,
			&i.CoolingExemptIds,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const touchProviderAccountRequestObservedAt = `-- name: TouchProviderAccountRequestObservedAt :exec
UPDATE provider_accounts
SET last_request_observed_at = $1::timestamptz
WHERE id = $2::bigint
  AND tenant_id = $3::bigint
  AND deleted_at IS NULL
  AND (
      last_request_observed_at IS NULL
      OR last_request_observed_at < $1::timestamptz
  )
`

type TouchProviderAccountRequestObservedAtParams struct {
	ObservedAt pgtype.Timestamptz `db:"observed_at" json:"observed_at"`
	ID         int64              `db:"id" json:"id"`
	TenantID   int64              `db:"tenant_id" json:"tenant_id"`
}

// 由异步请求完成事件调用,单调记录被动请求观测时间。
func (q *Queries) TouchProviderAccountRequestObservedAt(ctx context.Context, arg TouchProviderAccountRequestObservedAtParams) error {
	_, err := q.db.Exec(ctx, touchProviderAccountRequestObservedAt, arg.ObservedAt, arg.ID, arg.TenantID)
	return err
}
